<template><div class="app-container products"><div class="heading"><div><h2>平台商品</h2><p>自动同步平台商品与规格，按商家编码匹配 OMS SKU，集中处理绑定异常。</p></div><div><el-button v-hasPermi="['channel:platform:query']" @click="settings">同步与绑定设置</el-button><el-button v-hasPermi="['channel:product:pull']" type="primary" :disabled="!query.channelId" @click="pullVisible=true">立即同步</el-button></div></div>
<div v-if="policy" class="sync-bar"><el-tag :type="policy.auto_pull?'success':'info'">自动拉取{{ policy.auto_pull?'已开启':'已关闭' }}</el-tag><el-tag :type="policy.auto_bind?'success':'info'">自动绑定{{ policy.auto_bind?'已开启':'已关闭' }}</el-tag><span>最近成功：{{ policy.last_success_at || '尚无成功记录' }}</span><span>下次同步：{{ policy.auto_pull?policy.next_run_at:'—' }}</span><el-button type="text" @click="showTasks">{{ policy.running.length ? '查看进行中任务 '+policy.running[0].id : '查看拉取任务' }}</el-button></div><el-alert v-if="policy&&policy.last_error" :title="policy.last_error" type="warning" :closable="false"/>
<div class="counts"><div v-for="card in cards" :key="card.key" @click="quick(card.state)"><span>{{ card.name }}</span><strong>{{ counts[card.key] == null ? '—' : counts[card.key] }}</strong></div></div><el-tabs v-model="tab" @tab-click="tabChanged"><el-tab-pane label="全部商品" name="ALL"/><el-tab-pane label="待绑定" name="UNBOUND"/><el-tab-pane label="待核对" name="REVIEW"/><el-tab-pane label="部分已绑定" name="PARTIAL"/><el-tab-pane label="已全部绑定" name="BOUND"/></el-tabs>
<el-form inline size="small" class="filters" @submit.native.prevent="search"><el-form-item label="店铺"><el-select v-model="query.channelId" filterable clearable @change="shopChanged"><el-option v-for="s in shops" :key="s.channel_id" :value="s.channel_id" :label="s.channel_name"/></el-select></el-form-item><el-form-item label="关键词"><el-input v-model.trim="query.keyword" clearable placeholder="名称 / 商家编码 / 平台 ID / OMS SKU" style="width:310px" @keyup.enter.native="search"/></el-form-item><el-form-item label="上架状态"><el-select v-model="query.listing" clearable style="width:145px"><el-option label="出售中" value="onsale"/><el-option label="仓库中" value="instock"/></el-select></el-form-item><el-button type="primary" @click="search">查询</el-button><el-button @click="refresh">刷新</el-button><el-button :disabled="!query.channelId" @click="showTasks">同步异常 / 任务</el-button></el-form><el-alert v-if="error" :title="error" type="error" :closable="false"/>
<el-table v-loading="loading" :data="rows" row-key="id" :expand-row-keys="expandedKeys" @expand-change="expanded"><el-table-column type="expand"><template slot-scope="s"><div class="specs"><h4>平台规格与 OMS 绑定关系</h4><el-table :data="s.row.skus" size="small"><el-table-column label="平台规格" min-width="230"><template slot-scope="c"><strong>{{ c.row.spec_name || '无规格' }}</strong><div class="muted">SKU ID：{{ c.row.sku_id }}</div><div>商家编码：{{ c.row.outer_id || '未填写' }}</div></template></el-table-column><el-table-column label="拉取时库存" prop="platform_quantity" width="120"/><el-table-column label="绑定情况" width="150"><template slot-scope="c"><el-tag :type="tone(c.row)" size="mini">{{ state(c.row) }}</el-tag><div class="muted">{{ source(c.row.binding_source) }}</div></template></el-table-column><el-table-column label="OMS 商品 / SKU" min-width="230"><template slot-scope="c">{{ c.row.oms_goods_name || '尚未绑定' }}<div>{{ c.row.oms_sku_sn }}</div><div class="muted">{{ c.row.binding_reason || c.row.match_issue || '等待自动匹配' }}</div></template></el-table-column><el-table-column label="操作" width="170"><template slot-scope="c"><el-button v-hasPermi="['channel:product:bind']" type="text" @click="edit(c.row,s.row)">{{ c.row.binding_state==='BOUND'?'查看 / 更换绑定':c.row.binding_state==='REVIEW'?'核对绑定':'处理绑定' }}</el-button></template></el-table-column></el-table><pagination v-if="s.row.spec_count>50" :total="Number(s.row.spec_count)" :page="s.row.specPage||1" :limit="50" :page-sizes="[50]" @pagination="specPage(s.row,$event)"/></div></template></el-table-column><el-table-column label="平台商品" min-width="350"><template slot-scope="s"><div class="identity"><el-image v-if="s.row.pic_url" :src="s.row.pic_url" fit="contain" class="thumb"/><div><strong>{{ s.row.title }}</strong><div class="muted">商品 ID：{{ s.row.item_id }} <el-button v-clipboard:copy="s.row.item_id" type="text" icon="el-icon-document-copy"/></div></div></div></template></el-table-column><el-table-column label="店铺 / 状态" min-width="180"><template slot-scope="s">{{ s.row.channel_name }}<div><el-tag size="mini" type="info">{{ listing(s.row.listing_state) }}</el-tag></div></template></el-table-column><el-table-column label="规格 / 绑定情况" min-width="190"><template slot-scope="s"><strong>有效绑定 {{ s.row.bound_count }} / {{ s.row.sku_count }}</strong><div v-if="s.row.review_count" class="warn">{{ s.row.review_count }} 个规格待核对</div><div v-else class="muted">{{ !s.row.sku_count?'规格已移除':s.row.bound_count===s.row.sku_count?'全部已绑定':s.row.bound_count?'部分已绑定':'待绑定' }}</div></template></el-table-column><el-table-column label="最近拉取" min-width="170"><template slot-scope="s">{{ s.row.last_pull_at }}<div class="muted">任务 {{ s.row.last_task_id || '—' }}</div></template></el-table-column><el-table-column label="操作" width="190" fixed="right"><template slot-scope="s"><el-button type="text" @click="detail(s.row)">详情 / 规格</el-button><el-button v-hasPermi="['channel:product:pull']" type="text" @click="pullOne(s.row)">更新</el-button><el-button v-hasPermi="['channel:platform:log']" type="text" @click="detail(s.row,'logs')">交互记录</el-button></template></el-table-column></el-table><pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="load"/><p class="muted">平台信息来自最近成功拉取的本地快照，库存为拉取时数量。自动绑定不会开启平台库存写入。</p>
<el-dialog title="同步平台商品" :visible.sync="pullVisible" width="620px" append-to-body><el-form label-position="top"><el-form-item label="拉取范围"><el-radio-group v-model="pullMode"><el-radio label="ALL">全店商品（出售中与仓库中）</el-radio><el-radio label="IDS">指定商品 ID</el-radio></el-radio-group></el-form-item><el-form-item v-if="pullMode==='IDS'" label="商品 ID，用换行或逗号分隔，最多100个"><el-input v-model="pullIds" type="textarea" :rows="5"/></el-form-item></el-form><el-alert title="后台分页执行，成功拉取后按店铺规则自动匹配。可在同步任务中查看进度和失败原因。" type="info" :closable="false"/><span slot="footer"><el-button @click="pullVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="submitPull">提交同步</el-button></span></el-dialog>
<el-drawer title="平台商品同步任务" :visible.sync="tasksVisible" size="min(1050px,96vw)" append-to-body><div class="workspace"><el-button size="small" @click="showTasks">刷新进度</el-button><el-table :data="tasks"><el-table-column prop="id" label="任务" width="70"/><el-table-column label="范围 / 阶段"><template slot-scope="s">{{ s.row.mode==='ALL'?'全店':'指定商品' }} · {{ phases[s.row.phase] }}</template></el-table-column><el-table-column label="结果"><template slot-scope="s">{{ taskStates[s.row.state] }}<div class="muted">成功 {{ s.row.completed }} / 待更新 {{ s.row.total }}</div><div class="warn">{{ s.row.last_error }}</div></template></el-table-column><el-table-column prop="create_time" label="提交时间"/><el-table-column label="操作" width="160"><template slot-scope="s"><el-button type="text" @click="taskDetail(s.row)">查看</el-button><el-button v-if="['FAILED','PARTIAL'].includes(s.row.state)" v-hasPermi="['channel:product:pull']" type="text" @click="retry(s.row)">重试</el-button></template></el-table-column></el-table><template v-if="selectedTask"><h3>任务 {{ selectedTask.id }} · 失败商品</h3><el-table :data="selectedTask.failures"><el-table-column prop="item_id" label="商品 ID"/><el-table-column prop="last_error" label="失败原因"/></el-table></template></div></el-drawer>
<el-drawer title="平台商品详情" :visible.sync="detailVisible" size="min(1150px,96vw)" append-to-body><div v-if="selected" class="workspace"><div class="identity"><el-image v-if="selected.pic_url" :src="selected.pic_url" class="thumb"/><div><h3>{{ selected.title }}</h3><p>{{ selected.channel_name }} · 商品 {{ selected.item_id }}</p><p class="muted">最近成功拉取 {{ selected.last_pull_at }}</p></div></div><el-tabs v-model="detailTab"><el-tab-pane label="平台商品信息" name="platform"/><el-tab-pane label="OMS 绑定关系" name="bindings"/><el-tab-pane v-if="$auth.hasPermi('channel:platform:log')" label="同步与交互记录" name="logs"/></el-tabs><template v-if="detailTab!=='logs'"><el-descriptions v-if="detailTab==='platform'" :column="2" border size="small"><el-descriptions-item label="上下架状态">{{ listing(selected.listing_state) }}</el-descriptions-item><el-descriptions-item label="平台更新时间">{{ selected.platform_modified || '平台未返回' }}</el-descriptions-item></el-descriptions><el-table :data="selected.skus" size="small"><el-table-column label="平台规格 / 编码"><template slot-scope="s">{{ s.row.spec_name || '无规格' }}<div>{{ s.row.outer_id || '无商家编码' }}</div><div class="muted">SKU {{ s.row.sku_id }}</div></template></el-table-column><el-table-column label="绑定 / 来源"><template slot-scope="s">{{ state(s.row) }}<div class="muted">{{ source(s.row.binding_source) }}</div></template></el-table-column><el-table-column label="OMS 商品"><template slot-scope="s">{{ s.row.oms_sku_sn || '尚未绑定' }}<div>{{ s.row.oms_goods_name }}</div><div class="muted">{{ s.row.binding_reason || s.row.match_issue }}</div></template></el-table-column><el-table-column label="操作" width="210"><template slot-scope="s"><el-button v-hasPermi="['channel:product:bind']" type="text" @click="edit(s.row,selected)">查看 / 处理绑定</el-button><el-button v-if="s.row.binding_state==='BOUND'" v-hasPermi="['channel:stockSync:query']" type="text" @click="stock(s.row)">库存同步</el-button></template></el-table-column></el-table><pagination v-if="selected.spec_count>50" :total="Number(selected.spec_count)" :page="selected.specPage||1" :limit="50" :page-sizes="[50]" @pagination="specPage(selected,$event)"/></template><product-interactions v-if="detailTab==='logs'" :key="selected.item_id" :channel-id="selected.channel_id" :item-id="selected.item_id"/></div></el-drawer><product-binding-drawer ref="binding" :queue="queue" :shop-name="bindingShop" @saved="saved"/>
</div></template>
<script>
import {productGet,productPost} from '@/api/channel/products'
import {settingsGet} from '@/api/channel/settings'
import {stockGet} from '@/api/channel/stockSync'
import ProductBindingDrawer from './ProductBindingDrawer'
import ProductInteractions from './ProductInteractions'
export default {name:'PlatformProducts',components:{ProductBindingDrawer,ProductInteractions},data(){return{query:{channelId:undefined,keyword:'',state:'',listing:'',pageNum:1,pageSize:20},tab:'ALL',shops:[],rows:[],total:0,counts:{},cards:[{key:'total',name:'有效规格',state:''},{key:'auto_bound',name:'自动绑定成功',state:'BOUND'},{key:'unbound',name:'待处理规格',state:'UNBOUND'},{key:'review',name:'待核对规格',state:'REVIEW'}],policy:null,error:'',loading:false,busy:false,seq:0,expandedKeys:[],pullVisible:false,pullMode:'ALL',pullIds:'',tasksVisible:false,tasks:[],selectedTask:null,detailVisible:false,detailTab:'platform',selected:null,bindingShop:'',phases:{ONSALE:'出售中列表',INVENTORY:'仓库中列表',DETAIL:'规格明细'},taskStates:{PENDING:'待执行',RUNNING:'同步中',SUCCESS:'已完成',PARTIAL:'部分失败',FAILED:'失败'}}},computed:{queue(){return this.rows.flatMap(r=>r.skus)}},async created(){const q=this.$route.query;this.query.channelId=q.channelId?Number(q.channelId):undefined;try{this.shops=(await productGet('/options')).data.shops;await this.refresh();if(q.tasks&&this.query.channelId)this.showTasks();this.startPolling()}catch(_){this.error='商品目录加载失败，请刷新重试'}},watch:{'$route.fullPath'(){if(this.$route.path!=='/oms-channel/platformProducts')return;const q=this.$route.query;const channel=q.channelId?Number(q.channelId):undefined;if(channel!==this.query.channelId){this.query={channelId:channel,keyword:'',state:'',listing:'',pageNum:1,pageSize:20};this.tab='ALL';this.selected=null;this.expandedKeys=[];this.tasksVisible=false;this.refresh()}if(q.tasks&&channel)this.showTasks()}},activated(){this.startPolling()},deactivated(){clearInterval(this.timer)},beforeDestroy(){this.seq++;clearInterval(this.timer)},methods:{startPolling(){clearInterval(this.timer);this.timer=setInterval(()=>{if(document.hidden||!this.query.channelId||this.loading||this.busy||this.$refs.binding&&this.$refs.binding.visible)return;this.load();if(this.tasksVisible)this.showTasks(false)},15000)},listing(s){return {onsale:'出售中',instock:'仓库中',unknown:'状态待核对'}[s]||s},source(s){return {AUTO:'自动绑定',MANUAL:'人工处理'}[s]||'—'},state(r){return !r.present?'规格已移除':{BOUND:'已绑定',UNBOUND:'待绑定',IGNORED:'已忽略',REVIEW:'待核对'}[r.binding_state]},tone(r){return r.binding_state==='BOUND'?'success':r.binding_state==='REVIEW'?'warning':'info'},expanded(row,rows){this.expandedKeys=rows.map(r=>r.id);if(rows.includes(row))this.ensureSpecs(row)},async ensureSpecs(row,page=1){if(row.specLoaded&&row.specPage===page)return;const r=(await productGet('/items/'+row.channel_id+'/'+row.item_id+'/skus',{pageNum:page,pageSize:50})).data;this.$set(row,'skus',r.rows);this.$set(row,'specPage',page);this.$set(row,'specLoaded',true)},specPage(row,event){this.ensureSpecs(row,event.page)},settings(){this.$router.push({path:'/oms-channel/settings',query:{tab:'products',channelId:this.query.channelId}})},quick(s){this.query.state=s;this.tab=s||'ALL';this.search()},tabChanged(){this.query.state=this.tab==='ALL'?'':this.tab;this.search()},search(){this.query.pageNum=1;this.load()},shopChanged(){this.tasks=[];this.selectedTask=null;this.query.pageNum=1;this.refresh()},async refresh(){await this.load();if(this.tasksVisible)await this.showTasks(false)},async load(){const seq=++this.seq;this.loading=true;this.error='';try{const jobs=[productGet('/items',this.query),productGet('/summary',{channelId:this.query.channelId})];if(this.query.channelId)jobs.push(settingsGet('/products/'+this.query.channelId));const r=await Promise.all(jobs);if(seq!==this.seq)return;this.rows=r[0].data.rows;for(const row of this.rows)if(this.expandedKeys.includes(row.id)||this.selected&&this.selected.id===row.id)this.ensureSpecs(row);this.total=r[0].data.total;this.counts=r[1].data;this.policy=r[2]?r[2].data:null;if(this.selected){const fresh=this.rows.find(x=>x.id===this.selected.id);if(fresh)this.selected=fresh}}catch(_){if(seq===this.seq)this.error='商品目录读取失败，请刷新重试'}finally{if(seq===this.seq)this.loading=false}},detail(row,tab='platform'){this.selected=row;this.detailTab=tab;this.detailVisible=true;if(tab!=='logs')this.ensureSpecs(row)},edit(row,item){this.bindingShop=item.channel_name;this.$refs.binding.open(row)},saved(){this.load()},async stock(row){const r=await stockGet('',{channelId:row.channel_id,skuSn:row.oms_sku_sn,pageNum:1,pageSize:1});this.$router.push({path:'/oms-inventory/platformStock',query:r.data.rows.length?{id:r.data.rows[0].id}:{channelId:row.channel_id,skuSn:row.oms_sku_sn,create:'1'}})},async submitPull(){const ids=[...new Set(this.pullIds.split(/[\s,，]+/).filter(Boolean))];if(this.pullMode==='IDS'&&(!ids.length||ids.length>100||ids.some(x=>!(/^[1-9][0-9]{0,18}$/).test(x))))return this.$message.warning('请填写1至100个有效平台商品 ID');this.busy=true;try{await productPost('/pull/'+this.query.channelId,{mode:this.pullMode,item_ids:ids});this.pullVisible=false;this.$message.success('已提交后台同步');await this.showTasks()}finally{this.busy=false}},async pullOne(row){await productPost('/pull/'+row.channel_id,{mode:'IDS',item_ids:[row.item_id]});this.$message.success('已提交商品更新，可在同步任务查看结果')},async showTasks(reload=true){if(!this.query.channelId)return;this.tasksVisible=true;this.tasks=(await productGet('/pull/'+this.query.channelId+'/tasks')).data;if(reload)this.load()},async taskDetail(row){this.selectedTask=(await productGet('/tasks/'+row.id)).data},async retry(row){await productPost('/tasks/'+row.id+'/retry');this.$message.success('已提交重试');this.showTasks()}}}
</script><style scoped>.heading,.sync-bar,.identity{display:flex;align-items:center;justify-content:space-between;gap:16px}.heading h2{margin:0 0 8px}.heading p,.muted{color:#7f8b9d;font-size:13px;line-height:1.7}.sync-bar{justify-content:flex-start;flex-wrap:wrap;padding:14px;background:#f5f8fc;margin:18px 0;font-size:13px}.counts{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:20px 0}.counts>div{padding:18px 22px;background:#f7f9fc;border:1px solid #e1e8f0;border-radius:8px;cursor:pointer}.counts strong{display:block;font-size:26px;margin-top:8px;color:#263d54}.filters{margin:16px 0}.identity{justify-content:flex-start}.thumb{width:65px;height:65px;flex-shrink:0}.specs{padding:8px 35px 20px;background:#f8fafc}.warn{color:#a76812;font-size:13px}.workspace{padding:0 24px 30px}.products .el-table .el-button{margin-left:8px}@media(max-width:950px){.counts{grid-template-columns:1fr 1fr}.heading{align-items:flex-start;flex-wrap:wrap}}</style>
